function vne(t, r) {
  if (t === r) return !0
  if (!t || !r) return !1
  const e = Object.keys(t),
    n = Object.keys(r)
  if (e.length !== n.length) return !1
  for (const i of e) {
    const a = t[i],
      s = r[i]
    if ((a ?? '') !== (s ?? '')) return !1
  }
  return !0
}
